#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14b: Users in the admin dashboard
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part, Users in the dashboard's sidebar is live:
#   * every wallet that signed in: name, joined, last sign in, videos,
#     storage, signed in or not; search by name or part of the address;
#     All or Suspended; sort by newest, last sign in, videos or storage
#   * a page per wallet: videos, usage this month and all time, activity
#   * actions, each written to the audit log:
#       Sign out everywhere
#       Suspend (a reason is needed): its sessions end and it cannot sign in
#         until lifted; the main site tells it so. Its shared videos stay up
#       Delete the data (type the address): the same as Delete my data
#   * a suspension is kept in its own table, so it outlives deleted data
#   * the Privacy Policy says a suspension record is kept
#
#   BACKEND    1 new file, 3 changed. Migration 020_suspensions (runs by itself)
#   DASHBOARD  4 new files, 3 changed. No packages
#   FRONTEND   1 changed
#
#   ./vm_users.sh            apply (needs Part 14a2 on the branch)
#   ./vm_users.sh --force    apply even if local files differ from GitHub
#   ./vm_users.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_admin_users"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_users_backups"

ADD=(
  "backend/src/lib/adminUsers.ts"
  "dashboard/src/lib/format.ts"
  "dashboard/src/app/(admin)/users/page.tsx"
  "dashboard/src/app/(admin)/users/[wallet]/page.tsx"
  "dashboard/.env.example"
)
MOD=(
  "backend/src/routes/admin.ts"
  "backend/src/routes/auth.ts"
  "backend/src/lib/migrations.ts"
  "dashboard/src/lib/api.ts"
  "dashboard/src/components/Shell.tsx"
  "dashboard/src/app/(admin)/page.tsx"
  "frontend/src/app/legal/privacy/page.tsx"
)
PRE_MOD=(
  "2fe475b4987b63237cd359f0299a89001428022f41b298a9d80f4a121d6382b6"
  "c906f17c57f50a7351319d54e16ccf2a862e4cdc0ed299da3d032581525715d9"
