  "fed4541a6cfe09d9b0e5df9ff129219e8801a738d8d2544fb15b8d1042b24373"
  "3e20431050da0cf8607b1d4a39cef44d882c3e6197ad84f8d5503783620f811a"
  "88fa70628bd66291032d4476851d1d659d2093b9eb97fd5fa06b43250bf0dcd3"
  "fcb198f8927cab15ef0b485a7e37bd2aade8432c9269dc85423158c5ec6980dc"
  "c35e9936342ab265c4673894f549ae1e547ac4900f1fe6e773b35a1076f216fd"
  "861e55fa73f81f212bb11c035f3547eec5a4bbdf842b36a4e5f57266a8f48246"
)
NEW_ADD=(
  "76809e4566c9e457780568c739445f16c168f22c1d24b6c5dced044069a18e50"
  "aab802b2b25be86083e2dd0b52f5d84855ad00f5e204906ef1c3adebadffe348"
  "0f99035be7ed5c354d25739a29e16cadc2988b990fc4baa7731bef6f31c81330"
  "883076f2dea7afd7c2ae181d5ae6dc42b83308430bd4af1e2d72645a6b7ffdc5"
  "336e2fc79868b792e0417f654aae64cdc08e6a033998bcae5b619b46faf98ceb"
)

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }
sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1; fi
}
bname() { printf '%s' "$1" | sed 's#/#__#g'; }

[ -d frontend ] && [ -d backend ] || die "Run from repo root (dir with backend/ and frontend/)."

BRANCH="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
if [ "$BRANCH" = "main" ]; then
  die "You are on main. This part is for the rebuild branch. Run: git checkout rebuild"
fi

restore_from() {
  local f
  for f in "${MOD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then mkdir -p "$(dirname "$f")"; cp "$1/$(bname "$f")" "$f"; fi
  done
  for f in "${ADD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then cp "$1/$(bname "$f")" "$f"; else rm -f "$f"; fi
  done
  # Folders this part made, once empty, go too.
  for f in "${ADD[@]}"; do
    d="$(dirname "$f")"
    while [ "$d" != "." ] && [ "$d" != "/" ] && rmdir "$d" 2>/dev/null; do d="$(dirname "$d")"; done
  done
}

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d "$BAKDIR"/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  restore_from "${LATEST%/}"
  say "Restored 7 changed files and removed 5 new files, from $LATEST"
  exit 0
fi

FORCE=0
[ "${1:-}" = "--force" ] && FORCE=1

if [ -f "${ADD[0]}" ] && grep -q "$MARKER" "${ADD[0]}" && grep -q "$MARKER" "backend/src/routes/admin.ts"; then
  say "Already applied ($MARKER marker present). Use --revert to undo."
  exit 0
fi

grep -q '"next": "14.2.35"' frontend/package.json 2>/dev/null || die "Part 14a2 is not on this branch. Run: git pull origin rebuild"

# ---- pre image check: every file must match what this part was built on ----
check_pre() {
  [ -f "$1" ] || die "$1 not found. Nothing changed."
  if [ "$(sha "$1")" != "$2" ]; then
    if [ "$FORCE" = "1" ]; then say "WARNING: $1 differs from GitHub rebuild (5cfa6d2). Proceeding (--force)."
    else die "$1 differs from the GitHub rebuild version this part was built on (5cfa6d2). Nothing changed. Run git pull origin rebuild, push or stash local edits, or run again with --force."; fi
  fi
}
i=0; for f in "${MOD[@]}"; do check_pre "$f" "${PRE_MOD[$i]}"; i=$((i+1)); done
for f in "${ADD[@]}"; do
  if [ -f "$f" ] && [ "$FORCE" != "1" ]; then die "$f already exists but is not this part's version. Nothing changed. Run again with --force to overwrite it."; fi
done

# ---- decode + verify every payload BEFORE touching anything ----
TMPD="$(mktemp -d)"
trap 'rm -rf "$TMPD"' EXIT
verify() {
  [ -s "$1" ] || die "$3: base64 decode produced an empty file. Nothing written."
  [ "$(sha "$1")" = "$2" ] || die "$3: payload checksum mismatch (script was corrupted in transit). Nothing written."
}

