B64_A3
verify "$TMPD/a3" "${NEW_ADD[3]}" "dashboard/src/app/(admin)/users/[wallet]/page.tsx"

base64 -d > "$TMPD/a4" <<'B64_A4' || die "dashboard/.env.example: base64 decode failed."
IyB2bV9hZG1pbjogdGhlIFZpZGVvTWluZCBBUEkgdGhpcyBkYXNoYm9hcmQgdGFsa3MgdG8uCk5F
WFRfUFVCTElDX0FQSV9VUkw9aHR0cDovL2xvY2FsaG9zdDo0MDAwCg==
B64_A4
verify "$TMPD/a4" "${NEW_ADD[4]}" "dashboard/.env.example"

grep -q "$MARKER" "$TMPD/a0"                                   || die "adminUsers.ts payload missing marker. Aborting."
grep -q 'export async function suspendUser' "$TMPD/a0"           || die "adminUsers.ts payload is wrong. Aborting."
grep -q 'export function bytes' "$TMPD/a1"                       || die "format.ts payload is wrong. Aborting."
grep -q 'Search by name or wallet address' "$TMPD/a2"            || die "users page payload is wrong. Aborting."
grep -q 'Suspend this wallet' "$TMPD/a3"                         || die "wallet page payload is wrong. Aborting."
grep -q "$MARKER" "$TMPD/m0"                       || die "routes/admin.ts payload missing marker. Aborting."
grep -q 'SameSite=Strict' "$TMPD/m0"                || die "routes/admin.ts payload lost 14a. Aborting."
grep -q 'SUSPENDED_MESSAGE' "$TMPD/m1"              || die "routes/auth.ts payload is wrong. Aborting."
grep -q '020_suspensions' "$TMPD/m2"             || die "migrations.ts payload missing 020. Aborting."
grep -q '019_admin' "$TMPD/m2"                   || die "migrations.ts payload lost 019. Aborting."
grep -q 'export const suspendUser' "$TMPD/m3"         || die "dashboard api.ts payload is wrong. Aborting."
grep -q 'href: "/users"' "$TMPD/m4"         || die "Shell.tsx payload is wrong. Aborting."
grep -q 'user_suspended' "$TMPD/m5"          || die "Overview payload is wrong. Aborting."
grep -q 'record of the suspension' "$TMPD/m6" || die "privacy page payload is wrong. Aborting."
say "12 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Users (Part 14b)."
say "Migration 020_suspensions runs when the backend starts. Nothing to install."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_users.sh --revert"
